'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  CircleCheckIcon,
  ClockIcon,
  CreditCardIcon,
  DownloadIcon,
  FolderIcon,
  LayersIcon,
  RotateCcwIcon,
  Trash2Icon,
  UsersIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Input } from '@/registry/ndeko/ui/input';

import {
  ActionButton,
  useTimedAction,
  type ActionLabels,
  type ActionState,
} from './_parts/action-button';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { rowVariantsOf } from './_parts/motion';
import { WORKSPACE_NAME } from './_parts/people';
import { Swap } from './_parts/swap';

type Consequence = { id: string; icon: Icon; text: string };

const CONSEQUENCES: Consequence[] = [
  {
    id: 'projects',
    icon: FolderIcon,
    text: '12 projects and their 1,240 tasks are deleted',
  },
  {
    id: 'members',
    icon: UsersIcon,
    text: '18 members lose access at once',
  },
  {
    id: 'time',
    icon: ClockIcon,
    text: 'Time logs, timesheets and reports are erased',
  },
  {
    id: 'billing',
    icon: CreditCardIcon,
    text: 'The Team plan stops at the end of the billing period',
  },
];

const DELETE_LABELS: ActionLabels = {
  idle: 'Delete workspace',
  working: 'Deleting',
  done: 'Deleted',
};

const EXPORT_LABELS: ActionLabels = {
  idle: 'Export the data first',
  working: 'Preparing the export',
  done: 'Export sent by e-mail',
};

const WORKSPACE_GEM = { '--gem': 'var(--primary)' } as React.CSSProperties;

function shownStateOf(state: ActionState, isDeleted: boolean): ActionState {
  if (isDeleted) {
    return 'done';
  }
  return state;
}

function WorkspaceCard() {
  return (
    <div className='bg-card hairline-ring ring-border flex items-center gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <span
        style={WORKSPACE_GEM}
        className='gem-plate flex size-10 shrink-0 items-center justify-center rounded-lg'
      >
        <LayersIcon className='size-5' strokeWidth={2} />
      </span>
      <div className='flex min-w-0 flex-col gap-0.5'>
        <div className='flex items-center gap-2'>
          <p className='truncate text-sm font-medium'>{WORKSPACE_NAME}</p>
          <Chip color='var(--primary)'>Team plan</Chip>
        </div>
        <p className='text-muted-foreground truncate text-xs tabular-nums'>
          18 members · 12 projects · since March 2024
        </p>
      </div>
    </div>
  );
}

function ConsequenceList() {
  return (
    <ul
      aria-label='What deleting does'
      className='bg-destructive/[0.05] flex flex-col gap-2.5 rounded-xl p-3.5'
    >
      {CONSEQUENCES.map((consequence) => {
        const ConsequenceGlyph = consequence.icon;

        return (
          <li
            key={consequence.id}
            className='flex items-start gap-2.5 text-[13px]'
          >
            <ConsequenceGlyph className='text-destructive-ink/80 mt-0.5 size-4 shrink-0' />
            {consequence.text}
          </li>
        );
      })}
    </ul>
  );
}

function DeleteWorkspaceContent() {
  const [typedName, setTypedName] = useState('');
  const [isDeleted, setIsDeleted] = useState(false);
  const deletion = useTimedAction();
  const exporting = useTimedAction();
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const fieldId = useId();
  const hintId = useId();
  const isMatch = typedName.trim() === WORKSPACE_NAME;
  const matchKey = String(isMatch);
  const isIdle = deletion.state === 'idle';
  const isDeleteDisabled = isIdle && !isMatch;
  const isLocked = deletion.isBusy || isDeleted;
  const shownState = shownStateOf(deletion.state, isDeleted);

  function changeTypedName(event: React.ChangeEvent<HTMLInputElement>) {
    setTypedName(event.target.value);
  }

  function markDeleted() {
    setIsDeleted(true);
  }

  function deleteWorkspace(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const canDelete = isMatch && !isDeleted;
    if (!canDelete) {
      return;
    }
    deletion.run(markDeleted);
  }

  function exportData() {
    exporting.run(() => {});
  }

  function restore() {
    setIsDeleted(false);
    setTypedName('');
  }

  return (
    <form onSubmit={deleteWorkspace} className='flex flex-col gap-4'>
      <ModalHeader>
        <ModalTitle>{`Delete the ${WORKSPACE_NAME} workspace`}</ModalTitle>
        <ModalDescription>
          It goes for everyone in it. Owners can restore it for 30 days, then it
          is gone for good
        </ModalDescription>
      </ModalHeader>
      <WorkspaceCard />
      <ConsequenceList />
      <ActionButton
        type='button'
        variant='link'
        size='sm'
        state={exporting.state}
        labels={EXPORT_LABELS}
        idleIcon={<DownloadIcon />}
        onClick={exportData}
        className='-ml-1 self-start px-1'
      />
      <div className='flex flex-col gap-1.5'>
        <label htmlFor={fieldId} className='text-[13px]'>
          Type <span className='font-medium'>{WORKSPACE_NAME}</span> to confirm
        </label>
        <div className='relative'>
          <Input
            id={fieldId}
            autoComplete='off'
            spellCheck={false}
            value={typedName}
            disabled={isLocked}
            aria-describedby={hintId}
            placeholder={WORKSPACE_NAME}
            onChange={changeTypedName}
            className='pr-9'
          />
          <Swap
            swapKey={matchKey}
            className='pointer-events-none absolute top-1/2 right-2.5 -translate-y-1/2'
          >
            {isMatch && (
              <CircleCheckIcon className='text-success-foreground size-4' />
            )}
          </Swap>
        </div>
        <p id={hintId} className='text-muted-foreground text-xs'>
          The name is case sensitive
        </p>
      </div>
      <AnimatePresence initial={false}>
        {isDeleted && (
          <motion.div
            key='deleted'
            variants={rowVariants}
            initial='hidden'
            animate='shown'
            exit='hidden'
          >
            <div className='bg-foreground/[0.03] flex items-center gap-3 rounded-xl p-3'>
              <p className='min-w-0 flex-1 text-[13px]'>
                {`${WORKSPACE_NAME} is deleted. It stays restorable from Settings until 5 December`}
              </p>
              <Button variant='outline' size='sm' onClick={restore}>
                <RotateCcwIcon />
                Restore
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <ModalFooter>
        <ModalCloseButton type='button' variant='ghost'>
          Cancel
        </ModalCloseButton>
        <ActionButton
          type='submit'
          variant='destructive'
          state={shownState}
          labels={DELETE_LABELS}
          idleIcon={<Trash2Icon />}
          disabled={isDeleteDisabled}
        />
      </ModalFooter>
    </form>
  );
}

export default function Modal13() {
  return (
    <ModalPreview triggerLabel='Open delete workspace' size='md'>
      <DeleteWorkspaceContent />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

